-- Description: Detects suspicious PowerShell invocation with a parameter substring
-- Converted by: Sigma Universal SIEM/EDR CLI

SELECT * FROM processes WHERE ((Image="*\\powershell.exe" OR Image="*\\pwsh.exe") AND (CommandLine LIKE '% -windowstyle h %' OR CommandLine LIKE '% -windowstyl h%' OR CommandLine LIKE '% -windowsty h%' OR CommandLine LIKE '% -windowst h%' OR CommandLine LIKE '% -windows h%' OR CommandLine LIKE '% -windo h%' OR CommandLine LIKE '% -wind h%' OR CommandLine LIKE '% -win h%' OR CommandLine LIKE '% -wi h%' OR CommandLine LIKE '% -win h %' OR CommandLine LIKE '% -win hi %' OR CommandLine LIKE '% -win hid %' OR CommandLine LIKE '% -win hidd %' OR CommandLine LIKE '% -win hidde %' OR CommandLine LIKE '% -NoPr %' OR CommandLine LIKE '% -NoPro %' OR CommandLine LIKE '% -NoProf %' OR CommandLine LIKE '% -NoProfi %' OR CommandLine LIKE '% -NoProfil %' OR CommandLine LIKE '% -nonin %' OR CommandLine LIKE '% -nonint %' OR CommandLine LIKE '% -noninte %' OR CommandLine LIKE '% -noninter %' OR CommandLine LIKE '% -nonintera %' OR CommandLine LIKE '% -noninterac %' OR CommandLine LIKE '% -noninteract %' OR CommandLine LIKE '% -noninteracti %' OR CommandLine LIKE '% -noninteractiv %' OR CommandLine LIKE '% -ec %' OR CommandLine LIKE '% -encodedComman %' OR CommandLine LIKE '% -encodedComma %' OR CommandLine LIKE '% -encodedComm %' OR CommandLine LIKE '% -encodedCom %' OR CommandLine LIKE '% -encodedCo %' OR CommandLine LIKE '% -encodedC %' OR CommandLine LIKE '% -encoded %' OR CommandLine LIKE '% -encode %' OR CommandLine LIKE '% -encod %' OR CommandLine LIKE '% -enco %' OR CommandLine LIKE '% -en %' OR CommandLine LIKE '% -executionpolic %' OR CommandLine LIKE '% -executionpoli %' OR CommandLine LIKE '% -executionpol %' OR CommandLine LIKE '% -executionpo %' OR CommandLine LIKE '% -executionp %' OR CommandLine LIKE '% -execution bypass%' OR CommandLine LIKE '% -executio bypass%' OR CommandLine LIKE '% -executi bypass%' OR CommandLine LIKE '% -execut bypass%' OR CommandLine LIKE '% -execu bypass%' OR CommandLine LIKE '% -exec bypass%' OR CommandLine LIKE '% -exe bypass%' OR CommandLine LIKE '% -ex bypass%' OR CommandLine LIKE '% -ep bypass%' OR CommandLine LIKE '% /windowstyle h %' OR CommandLine LIKE '% /windowstyl h%' OR CommandLine LIKE '% /windowsty h%' OR CommandLine LIKE '% /windowst h%' OR CommandLine LIKE '% /windows h%' OR CommandLine LIKE '% /windo h%' OR CommandLine LIKE '% /wind h%' OR CommandLine LIKE '% /win h%' OR CommandLine LIKE '% /wi h%' OR CommandLine LIKE '% /win h %' OR CommandLine LIKE '% /win hi %' OR CommandLine LIKE '% /win hid %' OR CommandLine LIKE '% /win hidd %' OR CommandLine LIKE '% /win hidde %' OR CommandLine LIKE '% /NoPr %' OR CommandLine LIKE '% /NoPro %' OR CommandLine LIKE '% /NoProf %' OR CommandLine LIKE '% /NoProfi %' OR CommandLine LIKE '% /NoProfil %' OR CommandLine LIKE '% /nonin %' OR CommandLine LIKE '% /nonint %' OR CommandLine LIKE '% /noninte %' OR CommandLine LIKE '% /noninter %' OR CommandLine LIKE '% /nonintera %' OR CommandLine LIKE '% /noninterac %' OR CommandLine LIKE '% /noninteract %' OR CommandLine LIKE '% /noninteracti %' OR CommandLine LIKE '% /noninteractiv %' OR CommandLine LIKE '% /ec %' OR CommandLine LIKE '% /encodedComman %' OR CommandLine LIKE '% /encodedComma %' OR CommandLine LIKE '% /encodedComm %' OR CommandLine LIKE '% /encodedCom %' OR CommandLine LIKE '% /encodedCo %' OR CommandLine LIKE '% /encodedC %' OR CommandLine LIKE '% /encoded %' OR CommandLine LIKE '% /encode %' OR CommandLine LIKE '% /encod %' OR CommandLine LIKE '% /enco %' OR CommandLine LIKE '% /en %' OR CommandLine LIKE '% /executionpolic %' OR CommandLine LIKE '% /executionpoli %' OR CommandLine LIKE '% /executionpol %' OR CommandLine LIKE '% /executionpo %' OR CommandLine LIKE '% /executionp %' OR CommandLine LIKE '% /execution bypass%' OR CommandLine LIKE '% /executio bypass%' OR CommandLine LIKE '% /executi bypass%' OR CommandLine LIKE '% /execut bypass%' OR CommandLine LIKE '% /execu bypass%' OR CommandLine LIKE '% /exec bypass%' OR CommandLine LIKE '% /exe bypass%' OR CommandLine LIKE '% /ex bypass%' 